// Processar comando ou mensagem do Telegram
const update = $json;
let messageData = {};
let isCommand = false;
let commandName = '';
let commandArgs = [];

// Verificar se é callback query (botão inline)
if (update.callback_query) {
  messageData = {
    chat_id: update.callback_query.message.chat.id,
    user_id: update.callback_query.from.id,
    username: update.callback_query.from.username,
    first_name: update.callback_query.from.first_name,
    message_id: update.callback_query.message.message_id,
    text: update.callback_query.data,
    is_callback: true,
    callback_query_id: update.callback_query.id
  };

  // Processar callback data
  const callbackData = update.callback_query.data;
  if (callbackData.startsWith('/')) {
    isCommand = true;
    const parts = callbackData.split(' ');
    commandName = parts[0].substring(1); // Remove /
    commandArgs = parts.slice(1);
  }
} else if (update.message) {
  messageData = {
    chat_id: update.message.chat.id,
    user_id: update.message.from.id,
    username: update.message.from.username,
    first_name: update.message.from.first_name,
    message_id: update.message.message_id,
    text: update.message.text || '',
    is_callback: false
  };

  // Verificar se é comando
  if (messageData.text.startsWith('/')) {
    isCommand = true;
    const parts = messageData.text.split(' ');
    commandName = parts[0].substring(1); // Remove /
    commandArgs = parts.slice(1);
  }
}

// Verificar se usuário tem permissão
const userId = messageData.user_id;
const allowedUsers = (process.env.TELEGRAM_ALLOWED_USERS || '').split(',').map(id => parseInt(id.trim()));
const isAuthorized = allowedUsers.includes(userId) || allowedUsers.length === 0;

return {
  json: {
    message_data: messageData,
    is_command: isCommand,
    command_name: commandName,
    command_args: commandArgs,
    is_authorized: isAuthorized,
    raw_update: update
  }
};

// Gerar menu principal ou resposta de comando
const dados = $json;
const comando = dados.command_name;
const args = dados.command_args;
const messageData = dados.message_data;

let resposta = '';
let keyboard = null;
let parseMode = 'HTML';

switch (comando) {
  case 'start':
  case 'menu':
    resposta = `🏠 <b>Sistema de Automação Imobiliária</b>\n\nOlá, ${messageData.first_name}! Bem-vindo ao painel de controle.\n\nEscolha uma opção abaixo:`;
    keyboard = {
      inline_keyboard: [
        [
          { text: '📊 Status do Sistema', callback_data: '/status' },
          { text: '👥 Clientes Ativos', callback_data: '/clientes' }
        ],
        [
          { text: '📅 Visitas Hoje', callback_data: '/visitas' },
          { text: '🚨 HITL Pendentes', callback_data: '/hitl' }
        ],
        [
          { text: '📈 Relatórios', callback_data: '/relatorios' },
          { text: '⚙️ Configurações', callback_data: '/config' }
        ]
      ]
    };
    break;

  case 'status':
    // Será preenchido com dados reais do Supabase
    resposta = `📊 <b>Status do Sistema</b>\n\n` +
               `🟢 Sistema: Online\n` +
               `👥 Clientes ativos: Carregando...\n` +
               `📨 Mensagens hoje: Carregando...\n` +
               `🚨 HITL pendentes: Carregando...\n` +
               `📅 Visitas agendadas: Carregando...\n\n` +
               `<i>Atualizando dados...</i>`;
    keyboard = {
      inline_keyboard: [
        [{ text: '🔄 Atualizar', callback_data: '/status' }],
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  case 'clientes':
    resposta = `👥 <b>Clientes Ativos</b>\n\nCarregando lista de clientes...`;
    keyboard = {
      inline_keyboard: [
        [{ text: '🔄 Atualizar', callback_data: '/clientes' }],
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  case 'visitas':
    resposta = `📅 <b>Visitas de Hoje</b>\n\nCarregando agenda...`;
    keyboard = {
      inline_keyboard: [
        [{ text: '🔄 Atualizar', callback_data: '/visitas' }],
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  case 'hitl':
    resposta = `🚨 <b>Solicitações HITL Pendentes</b>\n\nCarregando solicitações...`;
    keyboard = {
      inline_keyboard: [
        [{ text: '🔄 Atualizar', callback_data: '/hitl' }],
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  case 'aprovar':
    if (args.length === 0) {
      resposta = `❌ <b>Erro</b>\n\nUso: /aprovar [id_interacao]\n\nExemplo: /aprovar 123`;
    } else {
      const interacaoId = args[0];
      resposta = `✅ <b>Aprovação Processada</b>\n\nInteração ID: ${interacaoId}\nStatus: Aprovado\n\nA ação será executada automaticamente.`;
    }
    keyboard = {
      inline_keyboard: [
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  case 'responder':
    if (args.length < 2) {
      resposta = `❌ <b>Erro</b>\n\nUso: /responder [id_interacao] [mensagem]\n\nExemplo: /responder 123 Obrigado pelo contato!`;
    } else {
      const interacaoId = args[0];
      const mensagem = args.slice(1).join(' ');
      resposta = `💬 <b>Resposta Enviada</b>\n\nInteração ID: ${interacaoId}\nMensagem: "${mensagem}"\n\nResposta enviada ao cliente.`;
    }
    keyboard = {
      inline_keyboard: [
        [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
      ]
    };
    break;

  default:
    resposta = `❓ <b>Comando não reconhecido</b>\n\nComandos disponíveis:\n/menu - Menu principal\n/status - Status do sistema\n/clientes - Lista de clientes\n/visitas - Visitas do dia\n/hitl - Solicitações pendentes\n/aprovar [id] - Aprovar ação\n/responder [id] [msg] - Responder cliente`;
    keyboard = {
      inline_keyboard: [
        [{ text: '📋 Menu Principal', callback_data: '/menu' }]
      ]
    };
}

return {
  json: {
    chat_id: messageData.chat_id,
    message_id: messageData.message_id,
    resposta: resposta,
    keyboard: keyboard,
    parse_mode: parseMode,
    comando_processado: comando,
    callback_query_id: messageData.callback_query_id,
    precisa_dados: ['status', 'clientes', 'visitas', 'hitl'].includes(comando)
  }
};

// Atualizar resposta com dados reais
const respostaOriginal = $input.first().json;
const comando = respostaOriginal.comando_processado;

// Buscar dados dos inputs subsequentes
let dadosSistema = null;
let clientesAtivos = [];
let visitasHoje = [];
let hitlPendentes = [];

// Processar inputs de dados
const inputs = $input.all().slice(1); // Pular o primeiro que é a resposta original

for (const input of inputs) {
  if (input.json.clientes_ativos !== undefined) {
    dadosSistema = input.json;
  } else if (input.json.nome && input.json.telefone) {
    clientesAtivos.push(input.json);
  } else if (input.json.data_hora) {
    visitasHoje.push(input.json);
  } else if (input.json.requer_hitl !== undefined) {
    hitlPendentes.push(input.json);
  }
}

let novaResposta = respostaOriginal.resposta;
let novoKeyboard = respostaOriginal.keyboard;

switch (comando) {
  case 'status':
    if (dadosSistema) {
      novaResposta = `📊 <b>Status do Sistema</b>\n\n` +
                     `🟢 Sistema: Online\n` +
                     `👥 Clientes ativos: ${dadosSistema.clientes_ativos}\n` +
                     `📨 Mensagens hoje: ${dadosSistema.mensagens_hoje}\n` +
                     `🚨 HITL pendentes: ${dadosSistema.hitl_pendentes}\n` +
                     `📅 Visitas hoje: ${dadosSistema.visitas_hoje}\n` +
                     `🏠 Imóveis disponíveis: ${dadosSistema.imoveis_disponiveis}\n\n` +
                     `<i>Última atualização: ${new Date().toLocaleString('pt-BR')}</i>`;
    }
    break;

  case 'clientes':
    if (clientesAtivos.length > 0) {
      const listaClientes = clientesAtivos.map((cliente, index) => {
        const diasSemContato = cliente.dias_sem_contato || 0;
        const emoji = diasSemContato > 7 ? '🔴' : diasSemContato > 3 ? '🟡' : '🟢';
        return `${emoji} <b>${cliente.nome}</b>\n` +
               `   📞 ${cliente.telefone}\n` +
               `   🎯 ${cliente.tipo_interesse || 'N/A'}\n` +
               `   ⭐ Score: ${cliente.score_qualificacao || 0}\n` +
               `   📅 ${diasSemContato}d sem contato`;
      }).join('\n\n');

      novaResposta = `👥 <b>Clientes Ativos (${clientesAtivos.length})</b>\n\n${listaClientes}`;

      // Adicionar botões de ação
      novoKeyboard = {
        inline_keyboard: [
          [{ text: '📞 Ligar para Cliente', callback_data: '/ligar' }],
          [{ text: '💬 Enviar Mensagem', callback_data: '/mensagem' }],
          [{ text: '🔄 Atualizar', callback_data: '/clientes' }],
          [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
        ]
      };
    } else {
      novaResposta = `👥 <b>Clientes Ativos</b>\n\n📭 Nenhum cliente ativo encontrado.`;
    }
    break;

  case 'visitas':
    if (visitasHoje.length > 0) {
      const listaVisitas = visitasHoje.map((visita, index) => {
        const hora = new Date(visita.data_hora).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
        const statusEmoji = visita.status === 'confirmada' ? '✅' : visita.status === 'agendada' ? '📅' : '❓';
        return `${statusEmoji} <b>${hora}</b> - ${visita.cliente_nome}\n` +
               `   🏠 ${visita.imovel_codigo}\n` +
               `   📍 ${visita.imovel_endereco}\n` +
               `   👤 ${visita.corretor_nome || 'Sem corretor'}\n` +
               `   📞 ${visita.cliente_telefone}`;
      }).join('\n\n');

      novaResposta = `📅 <b>Visitas de Hoje (${visitasHoje.length})</b>\n\n${listaVisitas}`;
    } else {
      novaResposta = `📅 <b>Visitas de Hoje</b>\n\n📭 Nenhuma visita agendada para hoje.`;
    }
    break;

  case 'hitl':
    if (hitlPendentes.length > 0) {
      const listaHitl = hitlPendentes.map((hitl, index) => {
        const prioridadeEmoji = hitl.prioridade >= 4 ? '🔴' : hitl.prioridade >= 3 ? '🟡' : '🟢';
        const tempo = new Date(hitl.created_at).toLocaleString('pt-BR');
        const mensagemCurta = hitl.mensagem.length > 50 ? hitl.mensagem.substring(0, 50) + '...' : hitl.mensagem;
        return `${prioridadeEmoji} <b>ID ${hitl.id}</b> - ${hitl.cliente_nome}\n` +
               `   📱 ${hitl.canal.toUpperCase()}\n` +
               `   💬 "${mensagemCurta}"\n` +
               `   📞 ${hitl.cliente_telefone}\n` +
               `   🕐 ${tempo}`;
      }).join('\n\n');

      novaResposta = `🚨 <b>HITL Pendentes (${hitlPendentes.length})</b>\n\n${listaHitl}\n\n<i>Use /aprovar [ID] ou /responder [ID] [mensagem]</i>`;

      // Adicionar botões de ação rápida
      const botoesRapidos = hitlPendentes.slice(0, 3).map(hitl => [
        { text: `✅ Aprovar ${hitl.id}`, callback_data: `/aprovar ${hitl.id}` },
        { text: `💬 Responder ${hitl.id}`, callback_data: `/responder ${hitl.id}` }
      ]);

      novoKeyboard = {
        inline_keyboard: [
          ...botoesRapidos,
          [{ text: '🔄 Atualizar', callback_data: '/hitl' }],
          [{ text: '⬅️ Voltar ao Menu', callback_data: '/menu' }]
        ]
      };
    } else {
      novaResposta = `🚨 <b>HITL Pendentes</b>\n\n✅ Nenhuma solicitação pendente!\n\nTudo funcionando perfeitamente.`;
    }
    break;
}

return {
  json: {
    ...respostaOriginal,
    resposta: novaResposta,
    keyboard: novoKeyboard,
    dados_atualizados: true
  }
};

// Processar notificação para Telegram
const dados = $json;
const tipo = dados.tipo;

let mensagem = '';
let chatIds = process.env.TELEGRAM_ADMIN_CHAT_IDS?.split(',') || [];
let prioridade = 'normal';

switch (tipo) {
  case 'nova_solicitacao_hitl':
    const contexto = JSON.parse(dados.contexto || '{}');
    prioridade = dados.prioridade >= 4 ? 'alta' : 'normal';

    mensagem = `🚨 <b>Nova Solicitação HITL</b>\n\n` +
               `📋 ID: ${dados.interacao_id}\n` +
               `⚡ Prioridade: ${dados.prioridade}/5\n` +
               `📱 Canal: ${contexto.canal?.toUpperCase() || 'N/A'}\n` +
               `👤 Cliente: ${contexto.dados_entrada?.cliente?.nome || 'Novo cliente'}\n` +
               `💬 Mensagem: "${contexto.mensagem_original?.substring(0, 100) || 'N/A'}..."\n\n` +
               `<i>Use /hitl para ver todas as solicitações pendentes</i>`;
    break;

  case 'nova_captacao':
    const dadosCaptacao = JSON.parse(dados.dados || '{}');
    prioridade = dados.urgencia === 'alta' ? 'alta' : 'normal';

    mensagem = `🏠 <b>Nova Captação de Imóvel</b>\n\n` +
               `📋 Proprietário ID: ${dados.proprietario_id}\n` +
               `🏠 Imóvel ID: ${dados.imovel_id}\n` +
               `⚡ Urgência: ${dados.urgencia}\n` +
               `🏠 Tipo: ${dadosCaptacao.tipo_imovel || 'N/A'}\n` +
               `💰 Valor: ${dadosCaptacao.valor_pretendido ? 'R$ ' + dadosCaptacao.valor_pretendido.toLocaleString('pt-BR') : 'A definir'}\n\n` +
               `<i>Novo imóvel cadastrado para avaliação</i>`;
    break;

  case 'alerta_sistema':
    const alertas = JSON.parse(dados.alertas || '[]');
    const dashboard = JSON.parse(dados.dashboard || '{}');

    if (alertas.length > 0) {
      prioridade = alertas.some(a => a.tipo === 'warning') ? 'alta' : 'normal';

      const listaAlertas = alertas.map(alerta => {
        const emoji = alerta.tipo === 'warning' ? '⚠️' : 'ℹ️';
        return `${emoji} ${alerta.mensagem}`;
      }).join('\n');

      mensagem = `📊 <b>Alertas do Sistema</b>\n\n${listaAlertas}\n\n` +
                 `📈 <b>Status Atual:</b>\n` +
                 `• HITL Pendentes: ${dashboard.hitl_pendentes || 0}\n` +
                 `• Interações (15min): ${dashboard.interacoes_periodo || 0}\n` +
                 `• Tempo Resposta: ${Math.round(dashboard.tempo_resposta_medio || 0)}s`;
    }
    break;

  case 'relatorio_horario':
    const relatorio = JSON.parse(dados.relatorio || '{}');

    mensagem = `📊 <b>Relatório Horário</b>\n\n` +
               `📨 Interações: ${relatorio.resumo?.total_interacoes || 0}\n` +
               `👥 Clientes únicos: ${relatorio.resumo?.clientes_unicos || 0}\n` +
               `⏱️ Tempo médio: ${relatorio.resumo?.tempo_resposta_medio || 0}s\n` +
               `🚨 Taxa HITL: ${relatorio.resumo?.taxa_hitl || 0}%\n\n` +
               `📱 WhatsApp: ${relatorio.canais?.whatsapp || 0}\n` +
               `📧 E-mail: ${relatorio.canais?.email || 0}\n\n` +
               `📅 Visitas agendadas: ${relatorio.visitas?.agendadas || 0}\n` +
               `✅ Visitas realizadas: ${relatorio.visitas?.realizadas || 0}`;
    break;

  default:
    mensagem = `📢 <b>Notificação do Sistema</b>\n\nTipo: ${tipo}\nDados: ${JSON.stringify(dados).substring(0, 200)}...`;
}

return {
  json: {
    mensagem: mensagem,
    chat_ids: chatIds,
    prioridade: prioridade,
    tipo_original: tipo,
    dados_originais: dados
  }
};
